// What the user picked on the QuizDifficultyScreen. 'mixed' includes every
// difficulty band; the other three filter to just their own band.
export type QuizDifficultyChoice = 'easy' | 'medium' | 'hard' | 'mixed'

// Picks N random questions from the bank with no repeats. If a difficulty
// band is given, the pool is filtered to that band first; 'mixed' (or
// omitted) uses the whole bank. Used by the QuizScreen at session start
// so each play gets a fresh subset matched to the user's choice.
export function sampleQuestions(
  count: number,
  difficulty: QuizDifficultyChoice = 'mixed',
): QuizQuestion[] {
  const pool =
    difficulty === 'mixed'
      ? [...QUIZ_QUESTIONS]
      : QUIZ_QUESTIONS.filter((q) => q.difficulty === difficulty)
  const out: QuizQuestion[] = []
  const n = Math.min(count, pool.length)
  for (let i = 0; i < n; i++) {
    const idx = Math.floor(Math.random() * pool.length)
    out.push(pool[idx])
    pool.splice(idx, 1)
  }
  return out
}

// Returns a shuffled copy of the option indices [0,1,2,3]. The QuizScreen
// applies this once per question per session so the correct answer isn't
// always in the same slot — even if a question repeats across sessions.
export function shuffleOptionOrder(): [number, number, number, number] {
  const order: [number, number, number, number] = [0, 1, 2, 3]
  for (let i = order.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[order[i], order[j]] = [order[j], order[i]]
  }
  return order
}
